    /// <summary>
    /// Tests how a dictionary with case-sensitive string keys works.
    /// </summary>
    @Test
    public void testCaseSensitiveDictionary()
    {
        testCaseSensitiveDictionary(new StringToObjDictionary<Object>());
        testCaseSensitiveDictionary(new StringToObjDictionary<Object>(true));
    }

    private static void testCaseSensitiveDictionary(StringToObjDictionary<Object> dictionary)
    {
        // Add two values to a dictionary with keys which differ only by character case and
        // ensure that they are considered to be separate dictionary entries.
        dictionary.set("Iя", G_FIRST_VALUE);
        dictionary.set("iя", G_SECOND_VALUE);
        msAssert.areEqual(2, dictionary.getCount());
        msAssert.areEqual(G_FIRST_VALUE, dictionary.get("Iя"));
        msAssert.areEqual(G_SECOND_VALUE, dictionary.get("iя"));
        msAssert.isTrue(StringToObjDictionary.isNullSubstitute(dictionary.get("IЯ")));
        msAssert.isTrue(StringToObjDictionary.isNullSubstitute(dictionary.get("iЯ")));
        msAssert.isTrue(dictionary.containsKey("Iя"));
        msAssert.isTrue(dictionary.containsKey("iя"));
        msAssert.isFalse(dictionary.containsKey("IЯ"));
        msAssert.isFalse(dictionary.containsKey("iЯ"));

        // Remove one of the values and ensure that it is removed whereas the other one is kept.
        boolean isRemoved = dictionary.remove("Iя");
        msAssert.isTrue(isRemoved);
        msAssert.areEqual(1, dictionary.getCount());
        msAssert.isFalse(dictionary.containsKey("Iя"));
        msAssert.isTrue(dictionary.containsKey("iя"));
        msAssert.isTrue(StringToObjDictionary.isNullSubstitute(dictionary.get("Iя")));
        msAssert.areEqual(G_SECOND_VALUE, dictionary.get("iя"));

        // Ensure that the removed dictionary entry is not considered to be a duplicate while repeated adding.
        dictionary.add("Iя", G_FIRST_VALUE);
    }

    /// <summary>
    /// Tests how a dictionary with case-insensitive string keys works.
    /// </summary>
    @Test
    public void testCaseInsensitiveDictionary()
    {
        // Add two values to a dictionary with keys which differ only by character case and
        // ensure that they are considered to be a single dictionary entry.
        StringToObjDictionary<Object> dictionary = new StringToObjDictionary<Object>(false);
        dictionary.set("Iя", G_FIRST_VALUE);
        dictionary.set("iя", G_SECOND_VALUE);
        msAssert.areEqual(1, dictionary.getCount());
        msAssert.areEqual(G_SECOND_VALUE, dictionary.get("Iя"));
        msAssert.areEqual(G_SECOND_VALUE, dictionary.get("iя"));
        msAssert.areEqual(G_SECOND_VALUE, dictionary.get("IЯ"));
        msAssert.areEqual(G_SECOND_VALUE, dictionary.get("iЯ"));
        msAssert.isTrue(dictionary.containsKey("Iя"));
        msAssert.isTrue(dictionary.containsKey("iя"));
        msAssert.isTrue(dictionary.containsKey("IЯ"));
        msAssert.isTrue(dictionary.containsKey("iЯ"));

        // Remove the entry and ensure that it is not accessible anymore.
        boolean isRemoved = dictionary.remove("Iя");
        msAssert.isTrue(isRemoved);
        msAssert.areEqual(0, dictionary.getCount());
        msAssert.isFalse(dictionary.containsKey("Iя"));
        msAssert.isFalse(dictionary.containsKey("iя"));
        msAssert.isTrue(StringToObjDictionary.isNullSubstitute(dictionary.get("Iя")));
        msAssert.isTrue(StringToObjDictionary.isNullSubstitute(dictionary.get("iя")));

        // Ensure that keys which differ only by character case are considered to be duplicates while adding.
        dictionary.add("Iя", G_FIRST_VALUE);
        testAddDuplicate(dictionary, "iя");
    }

